function validate(input) {
  const [{ Salesperson = [], Customer = [], Sales = [] }] = input;
  const people = new Set(), customers = new Set(), sales = new Set();
  for (const [id, name] of Salesperson) {
    if (id === null || name === null) return 'Salesperson rows may not contain null.';
    if (people.has(id)) return `salesperson_id ${id} appears twice.`;
    people.add(id);
  }
  for (const [id, owner] of Customer) {
    if (id === null || owner === null) return 'Customer rows may not contain null.';
    if (customers.has(id)) return `customer_id ${id} appears twice.`;
    if (!people.has(owner)) return `Customer ${id} names unknown salesperson ${owner}.`;
    customers.add(id);
  }
  for (const [id, customer, price] of Sales) {
    if (id === null || customer === null || price === null) return 'Sales rows may not contain null.';
    if (sales.has(id)) return `sale_id ${id} appears twice.`;
    if (!customers.has(customer)) return `Sale ${id} names unknown customer ${customer}.`;
    sales.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const names = ['Alice', 'Bob', 'Jerry', 'Maya', 'Omar', 'Lena'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const people = small ? Math.floor(rand() * 5) : 300;
  const customers = people === 0 ? 0 : small ? Math.floor(rand() * 6) : 1500;
  const sales = customers === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  const Salesperson = [], Customer = [], Sales = [];
  for (let i = 0; i < people; i++) Salesperson.push([i + 1, pick(names)]);
  for (let i = 0; i < customers; i++) Customer.push([i + 1, 1 + Math.floor(rand() * people)]);
  const prices = [100, 250, 354, 500, 856, 892, 988];
  for (let i = 0; i < sales; i++) Sales.push([i + 1, 1 + Math.floor(rand() * customers), small ? pick(prices) : 1 + Math.floor(rand() * 1000)]);
  return [{ Salesperson, Customer, Sales }];
}
